using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            return WebSearcher.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a query and returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("The text to fetch from a URL")] string url) =>
        {
            return WebSearcher.FetchPageAsync(url);
        },
        "fetch_page",
        "Fetches the text content of a web page given its URL."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Body content of the note")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieves all previously saved research notes.")
};

// ---------------------------------------------------------------------------
// Chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to thoroughly research the given topic
        using the tools available to you.

        Follow this workflow:
        1. Search the web for information on the topic (multiple queries if needed).
        2. Fetch promising pages to get detailed content.
        3. Save important findings as notes using the save_note tool.
        4. After gathering enough information, retrieve your notes and produce a
           well-structured summary with key facts, organized under clear headings.

        Be thorough but concise. Cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}")
};

Console.WriteLine("Agent is working…\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrWhiteSpace(topic))
        throw new InvalidOperationException("A research topic is required.");
    return topic;
}

// ---------------------------------------------------------------------------
// Notebook – simple in-memory note-taking tool
// ---------------------------------------------------------------------------
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        Console.WriteLine($"  📝 Note saved: {title}");
    }

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Title} ({n.Timestamp:u})\n{n.Content}"));
    }
}

// ---------------------------------------------------------------------------
// WebSearcher – lightweight web search via DuckDuckGo HTML and page fetcher
// ---------------------------------------------------------------------------
static class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        }
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");
        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            return ParseSearchResults(html);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    public static async Task<string> FetchPageAsync(string url)
    {
        Console.WriteLine($"  📄 Fetching: {url}");
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            // Truncate to keep token usage reasonable
            return text.Length > 6000 ? text[..6000] + "\n\n[…truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }

    private static string ParseSearchResults(string html)
    {
        var results = new List<string>();
        var span = html.AsSpan();
        var marker = "class=\"result__snippet\"";

        int pos = 0;
        while (results.Count < 8)
        {
            int idx = html.IndexOf(marker, pos, StringComparison.Ordinal);
            if (idx < 0) break;

            int gt = html.IndexOf('>', idx + marker.Length);
            if (gt < 0) break;

            int end = html.IndexOf('<', gt + 1);
            if (end < 0) break;

            var snippet = StripHtml(html[(gt + 1)..end]).Trim();
            if (snippet.Length > 0)
                results.Add(snippet);

            pos = end;
        }

        // Also extract URLs
        var urls = new List<string>();
        pos = 0;
        var urlMarker = "class=\"result__url\"";
        while (urls.Count < 8)
        {
            int idx = html.IndexOf(urlMarker, pos, StringComparison.Ordinal);
            if (idx < 0) break;

            int gt = html.IndexOf('>', idx + urlMarker.Length);
            if (gt < 0) break;

            int end = html.IndexOf('<', gt + 1);
            if (end < 0) break;

            var u = StripHtml(html[(gt + 1)..end]).Trim();
            if (u.Length > 0)
                urls.Add(u);

            pos = end;
        }

        if (results.Count == 0)
            return "No results found.";

        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < results.Count; i++)
        {
            var source = i < urls.Count ? $" (source: {urls[i]})" : "";
            sb.AppendLine($"- {results[i]}{source}");
        }
        return sb.ToString();
    }

    private static string StripHtml(string html)
    {
        var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        text = System.Net.WebUtility.HtmlDecode(text);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }
}

